--
-- Table structure for table `Rain`
--

DROP TABLE IF EXISTS `Rain`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Rain` (
  `region_code` char(5) NOT NULL,
  `date_id` date NOT NULL,
  `status_code` char(3) NOT NULL COMMENT '기상 현상 코드 (FK)',
  `daily_rainfall` decimal(6,2) DEFAULT NULL COMMENT '일 강수량 (mm)',
  `humidity` decimal(4,1) DEFAULT NULL COMMENT '평균 습도 (%)',
  `wind_speed` decimal(4,1) DEFAULT NULL COMMENT '평균 풍속 (m/s)',
  `cloud_cover` decimal(3,1) DEFAULT NULL COMMENT '평균 전운량 (1/10)',
  PRIMARY KEY (`region_code`,`date_id`),
  KEY `date_id` (`date_id`),
  KEY `status_code` (`status_code`),
  CONSTRAINT `rain_ibfk_1` FOREIGN KEY (`region_code`) REFERENCES `Region` (`region_code`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rain_ibfk_2` FOREIGN KEY (`date_id`) REFERENCES `DateDim` (`date_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rain_ibfk_3` FOREIGN KEY (`status_code`) REFERENCES `WeatherStatusDim` (`status_code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

