DROP TABLE IF EXISTS `Region`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Region` (
  `region_code` char(5) NOT NULL COMMENT '지역 코드 (PK, 예: 01~75)',
  `region_name` varchar(50) NOT NULL COMMENT '지역명 (예: 서울, 제주)',
  `province` varchar(20) DEFAULT NULL COMMENT '광역자치단체명 (광역시 등은 NULL)',
  `popular_count` int DEFAULT '0' COMMENT '지역별 검색 횟수 (랭킹 분석용)',
  PRIMARY KEY (`region_code`),
  UNIQUE KEY `idx_region_name` (`region_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
